local ENGLISH = GetLocale and GetLocale() ~= "ruRU"
function ns.T(text)
    if not ENGLISH or type(text) ~= "string" then return text end
    local exact = EN[text]
    if exact then return exact end
    return text
end
ns.ENGLISH = ENGLISH
